def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    bg = Counter(x for row in grid for x in row).most_common(1)[0][0]

    # Locate full divider rows and columns.
    div_rows = [r for r in range(h)
                if len(set(grid[r])) == 1 and grid[r][0] != bg]
    div_cols = [c for c in range(w)
                if len({grid[r][c] for r in range(h)}) == 1
                and grid[0][c] != bg]

    def intervals(n, divs):
        result, start = [], 0
        for d in divs:
            if start < d:
                result.append((start, d))
            start = d + 1
        if start < n:
            result.append((start, n))
        return result

    rs = intervals(h, div_rows)
    cs = intervals(w, div_cols)
    out = [row[:] for row in grid]

    # Collect the non-background pattern by position within a tile.
    pattern = {}
    for r0, r1 in rs:
        for c0, c1 in cs:
            for r in range(r0, r1):
                for c in range(c0, c1):
                    value = grid[r][c]
                    if value != bg:
                        pattern[(r - r0, c - c0)] = value

    # Repeat the pattern in every tile.
    for r0, r1 in rs:
        for c0, c1 in cs:
            for (dr, dc), value in pattern.items():
                if r0 + dr < r1 and c0 + dc < c1:
                    out[r0 + dr][c0 + dc] = value
    return out
